(11, 0, 'visao1-7804.png', 'visao17804-9860_85x58.png', 'visao1-6271_68x68.png', 'visao17804-5435.png', 'ĐÁP ỨNG', '', 'MEET THE DEMAND', '', '', NULL, NULL, '', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;Các yêu cầu phức tạp về màu sơn, hiệu ứng, loại sơn...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;Meet the complex requirements of paint color, effect, paint type, coating coverage...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', 0, 1, 1, 'vi-sao', 0, 0, 0, 0, '', '', '', '', '', '支持定制', '&lt;p style=&quot;margin-right: 0cm; margin-left: 0cm; font-size: 12pt; font-family: &amp;quot;Times New Roman&amp;quot;, serif; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;&lt;span lang=&quot;ZH-CN&quot;&gt;满足对&lt;/span&gt;&lt;span lang=&quot;ZH-CN&quot;&gt;粉末颜色、效应、类型的复杂要求...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;font-family: Calibri, sans-serif;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n', 'visao17804-6470.png', 'visao17804-7461_85x58.png', '', 1659949376, 1661154787),
(12, 0, 'iconvisao2-9055.png', 'iconvisao29055-8047_85x58.png', 'iconvisao2-2340_68x68.png', 'iconvisao29055-3504.png', 'SẢN LƯỢNG', '', 'Quantity', '', '', NULL, NULL, '', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;Xưởng gia công sơn tĩnh điện đáp ứng trung bình 15 tấn trên ngày&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;Powder coating processing workshop meets an average of 15 tons per day&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', 0, 2, 1, 'vi-sao', 0, 0, 0, 0, '', '', '', '', '', '产量', '&lt;p&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;粉末厂可满足约15吨/天的需求...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;\r\n', 'iconvisao29055-9590.png', 'iconvisao29055-3356_85x58.png', '', 1659949405, 1661154792),
(13, 0, 'visao3-3520.png', 'visao33520-5317_85x58.png', 'visao3-5402_68x68.png', 'visao33520-6344.png', 'ĐÚNG TIẾN ĐỘ', '', 'ON SCHEDULE', '', '', NULL, NULL, '', '&lt;p&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;Thời gian gia công sơn tĩnh điện luôn đúng tiến độ theo hợp đồng đã thoả thuận.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '&lt;p&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;The time to apply powder coating is always on schedule according to the agreed contract.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', 0, 3, 1, 'vi-sao', 0, 0, 0, 0, '', '', '', '', '', '准时', '&lt;p&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;根据合同协议，粉末涂料准时交货。&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;\r\n', 'visao33520-8909.png', 'visao33520-717_85x58.png', '', 1659949438, 1661154798),
(14, 0, 'icon-doi-ngu-697.png', 'icon-doi-ngu-8212_85x58.png', 'icon-doi-ngu-2160_85x58.png', 'icon-doi-ngu-942.png', 'ĐỘI NGŨ', '', 'MANPOWER', '', '', NULL, NULL, '', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;Chúng tôi sở hữu đội ngũ hơn 200 công nhân, kỹ sư tay nghề cao, chuyên nghiệp.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', '&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-size:14px;&quot;&gt;We own a team of more than 200 workers, skilled and professional engineers.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n', 0, 4, 1, 'vi-sao', 0, 0, 0, 0, '', '', '', '', '', '团队', '&lt;p&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;span style=&quot;color:#FFFFFF;&quot;&gt;&lt;span style=&quot;line-height:1.0;&quot;&gt;&lt;span style=&quot;font-family:utm-avo;&quot;&gt;我们拥有200多员工、熟练和专业的工程师组成的团队。&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;\r\n', 'icon-doi-ngu-8887.png', 'icon-doi-ngu-7149_85x58.png', '', 1659949481, 1661154804),
